function countWinningSequences(s) {
  const MOD = 1000000007;
  const n = s.length;
  const moves = ['F', 'W', 'E'];
  const beats = new Map([['F', 'E'], ['W', 'F'], ['E', 'W']]);
  const gain = (bob, alice) => (bob === alice ? 0 : beats.get(bob) === alice ? 1 : -1);
  let dp = moves.map(() => new Array(2 * n + 1).fill(0));
  for (let m = 0; m < 3; m++) {
    dp[m][n + gain(moves[m], s[0])] = 1;
  }
  for (let i = 1; i < n; i++) {
    const next = moves.map(() => new Array(2 * n + 1).fill(0));
    for (let m = 0; m < 3; m++) {
      const step = gain(moves[m], s[i]);
      const otherA = dp[(m + 1) % 3];
      const otherB = dp[(m + 2) % 3];
      for (let lead = -i; lead <= i; lead++) {
        next[m][n + lead + step] = (otherA[n + lead] + otherB[n + lead]) % MOD;
      }
    }
    dp = next;
  }
  let count = 0;
  for (let m = 0; m < 3; m++) {
    for (let lead = 1; lead <= n; lead++) {
      count = (count + dp[m][n + lead]) % MOD;
    }
  }
  return count;
}

