function countWinningSequences(s) {
  // Plain search over Bob's moves round by round, remembering each (round, last move, lead).
  const MOD = 1000000007;
  const points = new Map([['FE', 1], ['WF', 1], ['EW', 1], ['EF', -1], ['FW', -1], ['WE', -1]]);
  const memo = new Map();
  const search = (round, last, lead) => {
    if (round === s.length) return lead > 0 ? 1 : 0;
    const key = `${round}|${last}|${lead}`;
    if (memo.has(key)) return memo.get(key);
    let ways = 0;
    for (const move of ['F', 'W', 'E']) {
      if (move === last) continue;
      ways = (ways + search(round + 1, move, lead + (points.get(move + s[round]) ?? 0))) % MOD;
    }
    memo.set(key, ways);
    return ways;
  };
  return search(0, '', 0);
}

