function generate(rand, size) {
  const n = size === 'large' ? 950 + Math.floor(rand() * 51) : 1 + Math.floor(rand() * 10);
  const pick = () => 'FWE'[Math.floor(rand() * 3)];
  // Some strings repeat one letter or a short pattern; the rest are random.
  const style = rand();
  const pattern = style < 0.2 ? pick() : style < 0.4 ? pick() + pick() + pick() : '';
  let s = '';
  for (let i = 0; i < n; i++) s += pattern ? pattern[i % pattern.length] : pick();
  return [s];
}
